-- Multi-user company membership, centralized permissions, invitations, assignments, and actor attribution.
begin;

create type public.member_role as enum ('owner','admin','estimator','project_manager','employee');
create type public.membership_status as enum ('invited','active','deactivated');

alter table public.projects add column if not exists employee_notes text;
alter table public.users add column if not exists phone text;
alter table public.users add column if not exists avatar_url text;
alter table public.users add column if not exists last_active_at timestamptz;

create table public.company_members (
  id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,
  role public.member_role not null,status public.membership_status not null default 'invited',email text not null,display_name text,last_active_at timestamptz,
  invited_by uuid references auth.users(id),invited_at timestamptz,accepted_at timestamptz,deactivated_at timestamptz,
  created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,user_id)
);
create unique index company_members_company_email_idx on public.company_members(company_id,lower(email));
create index company_members_user_status_idx on public.company_members(user_id,status);
create index company_members_company_role_status_idx on public.company_members(company_id,role,status);

create table public.team_invitations (
  id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,email text not null,
  role public.member_role not null,first_name text,last_name text,token_hash text not null unique,invited_by uuid not null references auth.users(id),
  invited_at timestamptz not null default now(),expires_at timestamptz not null,accepted_at timestamptz,revoked_at timestamptz,
  created_at timestamptz not null default now()
);
create index team_invitations_company_email_idx on public.team_invitations(company_id,lower(email));
create index team_invitations_expiry_idx on public.team_invitations(expires_at) where accepted_at is null and revoked_at is null;

create table public.project_members (
  project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,
  role_on_project text not null default 'crew',assigned_by uuid references auth.users(id),assigned_at timestamptz not null default now(),primary key(project_id,user_id)
);
create index project_members_user_idx on public.project_members(user_id,project_id);

create table public.audit_events (
  id bigint generated always as identity primary key,company_id uuid not null references public.companies(id) on delete cascade,user_id uuid references auth.users(id),
  user_name text,event_type text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now()
);
create index audit_events_company_created_idx on public.audit_events(company_id,created_at desc);
create index audit_events_company_user_idx on public.audit_events(company_id,user_id,created_at desc);
create index audit_events_company_module_idx on public.audit_events(company_id,entity_type,created_at desc);
alter table public.estimate_events add column if not exists user_id uuid references auth.users(id),add column if not exists user_name text,add column if not exists entity_type text,add column if not exists entity_id uuid;
alter table public.financial_events add column if not exists user_id uuid references auth.users(id),add column if not exists user_name text,add column if not exists entity_type text,add column if not exists entity_id uuid;
create or replace function public.attribute_estimate_event()returns trigger language plpgsql security definer set search_path=public as $$begin new.user_id:=coalesce(new.user_id,auth.uid());if new.user_id is not null then select coalesce(full_name,(select email from auth.users where id=new.user_id))into new.user_name from public.users where id=new.user_id;end if;new.entity_type:=coalesce(new.entity_type,case when new.change_order_id is not null then'change_order'else'estimate'end);new.entity_id:=coalesce(new.entity_id,new.change_order_id,new.estimate_id);return new;end $$;
create or replace function public.attribute_financial_event()returns trigger language plpgsql security definer set search_path=public as $$begin new.user_id:=coalesce(new.user_id,auth.uid());if new.user_id is not null then select coalesce(full_name,(select email from auth.users where id=new.user_id))into new.user_name from public.users where id=new.user_id;end if;new.entity_type:=coalesce(new.entity_type,case when new.payment_id is not null then'payment'when new.invoice_id is not null then'invoice'else'project'end);new.entity_id:=coalesce(new.entity_id,new.payment_id,new.invoice_id,new.project_id);return new;end $$;
drop trigger if exists attribute_estimate_event on public.estimate_events;create trigger attribute_estimate_event before insert on public.estimate_events for each row execute function public.attribute_estimate_event();
drop trigger if exists attribute_financial_event on public.financial_events;create trigger attribute_financial_event before insert on public.financial_events for each row execute function public.attribute_financial_event();

insert into public.company_members(company_id,user_id,role,status,email,display_name,accepted_at)
select c.id,c.owner_id,'owner','active',coalesce(u.email,''),coalesce(u.raw_user_meta_data->>'full_name',c.owner_name),c.created_at
from public.companies c join auth.users u on u.id=c.owner_id on conflict(company_id,user_id) do nothing;

create or replace function public.link_company_owner() returns trigger language plpgsql security definer set search_path=public as $$
declare owner_email text;owner_label text;begin update public.users set company_id=new.id where id=new.owner_id;select email,coalesce(raw_user_meta_data->>'full_name',new.owner_name)into owner_email,owner_label from auth.users where id=new.owner_id;insert into public.company_members(company_id,user_id,role,status,email,display_name,accepted_at)values(new.id,new.owner_id,'owner','active',coalesce(owner_email,''),owner_label,now())on conflict(company_id,user_id)do nothing;return new;end $$;

create or replace function public.active_member_role(target_company_id uuid) returns public.member_role language sql stable security definer set search_path=public as $$
  select role from public.company_members where company_id=target_company_id and user_id=auth.uid() and status='active' and company_id=(select company_id from public.users where id=auth.uid()) limit 1;
$$;
create or replace function public.is_active_company_member(target_company_id uuid) returns boolean language sql stable security definer set search_path=public as $$
  select public.active_member_role(target_company_id) is not null;
$$;
create or replace function public.has_company_permission(target_company_id uuid,permission_name text) returns boolean language sql stable security definer set search_path=public as $$
  select case public.active_member_role(target_company_id)
    when 'owner' then true
    when 'admin' then permission_name=any(array['dashboard.view','customers.view','customers.create','customers.edit','customers.delete','estimates.view','estimates.create','estimates.edit','estimates.send','estimates.delete','rate_library.view','rate_library.manage','projects.view','projects.create','projects.edit','change_orders.view','change_orders.create','change_orders.send','invoices.view','invoices.create','invoices.send','payments.view','payments.record','project_costs.view','project_costs.create','reports.view','reports.financial','team.view','team.manage','settings.company','financial.internal_costs','financial.profit','financial.margin','financial.revenue','audit.view'])
    when 'estimator' then permission_name=any(array['dashboard.view','customers.view','customers.create','customers.edit','estimates.view','estimates.create','estimates.edit','estimates.send','rate_library.view','financial.internal_costs'])
    when 'project_manager' then permission_name=any(array['dashboard.view','customers.view','projects.view','projects.edit','change_orders.view','change_orders.create','change_orders.send','invoices.view','invoices.create','invoices.send','project_costs.view','project_costs.create','financial.internal_costs'])
    when 'employee' then permission_name=any(array['dashboard.view','assigned_projects.view'])
    else false end;
$$;
-- Keep legacy owner/admin workflows safe while granular policies cover limited roles.
create or replace function public.owns_company(target_company_id uuid) returns boolean language sql stable security definer set search_path=public as $$
  select coalesce(public.active_member_role(target_company_id) in ('owner','admin'),false);
$$;
create or replace function public.protect_company_financial_settings()returns trigger language plpgsql set search_path=public as $$begin if (new.default_sales_tax,new.default_overhead,new.default_profit_markup,new.default_deposit,new.estimate_validity_days)is distinct from(old.default_sales_tax,old.default_overhead,old.default_profit_markup,old.default_deposit,old.estimate_validity_days)and not public.has_company_permission(old.id,'settings.financial')then raise exception 'Financial settings require Owner permission';end if;return new;end $$;
drop trigger if exists protect_company_financial_settings on public.companies;create trigger protect_company_financial_settings before update on public.companies for each row execute function public.protect_company_financial_settings();

alter table public.company_members enable row level security;alter table public.team_invitations enable row level security;alter table public.project_members enable row level security;alter table public.audit_events enable row level security;
create policy company_members_team_read on public.company_members for select using(public.has_company_permission(company_id,'team.view') or user_id=auth.uid());
create policy company_members_project_assign_read on public.company_members for select using(public.has_company_permission(company_id,'projects.edit'));
create policy invitations_team_read on public.team_invitations for select using(public.has_company_permission(company_id,'team.manage'));
create policy project_members_project_read on public.project_members for select using(exists(select 1 from public.projects p where p.id=project_id and public.has_company_permission(p.company_id,'projects.view')) or user_id=auth.uid());
create policy audit_events_authorized_read on public.audit_events for select using(public.has_company_permission(company_id,'audit.view'));

-- Limited-role row access. Existing owner policies continue to use owns_company.
create policy companies_active_member_read on public.companies for select using(public.is_active_company_member(id)and public.active_member_role(id)<>'employee');
create policy companies_admin_update on public.companies for update using(public.has_company_permission(id,'settings.company')) with check(public.has_company_permission(id,'settings.company'));
create policy customers_role_select on public.customers for select using(public.has_company_permission(company_id,'customers.view'));
create policy customers_role_insert on public.customers for insert with check(public.has_company_permission(company_id,'customers.create'));
create policy customers_role_update on public.customers for update using(public.has_company_permission(company_id,'customers.edit')) with check(public.has_company_permission(company_id,'customers.edit'));
create policy job_sites_role_select on public.job_sites for select using(public.has_company_permission(company_id,'customers.view'));
create policy job_sites_role_insert on public.job_sites for insert with check(public.has_company_permission(company_id,'customers.create'));
create policy job_sites_role_update on public.job_sites for update using(public.has_company_permission(company_id,'customers.edit')) with check(public.has_company_permission(company_id,'customers.edit'));
create policy estimates_role_select on public.estimates for select using(public.has_company_permission(company_id,'estimates.view') or (public.active_member_role(company_id)='project_manager' and status='approved'));
create policy estimates_role_insert on public.estimates for insert with check(public.has_company_permission(company_id,'estimates.create'));
create policy estimates_role_update on public.estimates for update using(public.has_company_permission(company_id,'estimates.edit')) with check(public.has_company_permission(company_id,'estimates.edit'));
create policy estimate_items_role_select on public.estimate_items for select using(public.has_company_permission(company_id,'financial.internal_costs'));
create policy estimate_items_role_insert on public.estimate_items for insert with check(public.has_company_permission(company_id,'estimates.create'));
create policy estimate_items_role_update on public.estimate_items for update using(public.has_company_permission(company_id,'estimates.edit')) with check(public.has_company_permission(company_id,'estimates.edit'));
create policy rates_role_select on public.rate_library for select using(public.has_company_permission(company_id,'rate_library.view'));
create policy projects_pm_select on public.projects for select using(public.active_member_role(company_id)='project_manager');
create policy invoices_pm_select on public.invoices for select using(public.active_member_role(company_id)='project_manager');
create policy invoice_items_pm_select on public.invoice_items for select using(public.active_member_role(company_id)='project_manager');
create policy project_costs_pm_select on public.project_costs for select using(public.active_member_role(company_id)='project_manager');
create policy change_orders_pm_select on public.change_orders for select using(public.active_member_role(company_id)='project_manager');
create policy change_order_items_pm_select on public.change_order_items for select using(public.active_member_role(company_id)='project_manager');
create policy change_orders_pm_insert on public.change_orders for insert with check(public.has_company_permission(company_id,'change_orders.create'));
create policy change_orders_pm_update on public.change_orders for update using(public.has_company_permission(company_id,'change_orders.create'))with check(public.has_company_permission(company_id,'change_orders.create'));
create policy change_order_items_pm_insert on public.change_order_items for insert with check(public.has_company_permission(company_id,'change_orders.create'));
create policy change_order_items_pm_update on public.change_order_items for update using(public.has_company_permission(company_id,'change_orders.create'))with check(public.has_company_permission(company_id,'change_orders.create'));

revoke insert,update,delete on public.company_members,public.team_invitations,public.project_members,public.audit_events from authenticated,anon;
grant select on public.company_members,public.team_invitations,public.project_members,public.audit_events to authenticated;

create or replace function public.write_audit(target_company uuid,event text,entity text,entity_uuid uuid default null,details jsonb default '{}') returns void language plpgsql security definer set search_path=public as $$
declare actor_name text;begin select coalesce(full_name,(select email from auth.users where id=auth.uid())) into actor_name from public.users where id=auth.uid();insert into public.audit_events(company_id,user_id,user_name,event_type,entity_type,entity_id,metadata)values(target_company,auth.uid(),actor_name,event,entity,entity_uuid,coalesce(details,'{}'));end $$;


create or replace function public.create_team_invitation(target_company uuid,target_email text,target_role public.member_role,first_name text default null,last_name text default null) returns text
language plpgsql security definer set search_path=public as $$
declare raw_token text;
begin
 if not public.has_company_permission(target_company,'team.manage') then raise exception 'Access denied';end if;
 if target_email is null or target_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'A valid email is required';end if;
 if target_role='owner' and public.active_member_role(target_company)<>'owner' then raise exception 'Only an Owner can invite another Owner';end if;
 if exists(select 1 from public.company_members where company_id=target_company and lower(email)=lower(trim(target_email)))then raise exception 'Membership already exists. Reactivate or change the existing member';end if;
 raw_token:=encode(extensions.gen_random_bytes(32),'hex');
 insert into public.team_invitations(company_id,email,role,first_name,last_name,token_hash,invited_by,expires_at)
 values(target_company,lower(trim(target_email)),target_role,nullif(trim(first_name),''),nullif(trim(last_name),''),encode(extensions.digest(raw_token,'sha256'),'hex'),auth.uid(),now()+interval '7 days');
 perform public.write_audit(target_company,'team_invitation_created','team_invitation',null,jsonb_build_object('email',lower(trim(target_email)),'role',target_role));
 return raw_token;
end $$;
create or replace function public.get_public_invitation(raw_token text) returns jsonb language sql stable security definer set search_path=public as $$
select jsonb_build_object('company_name',c.name,'email',i.email,'role',i.role,'first_name',i.first_name,'last_name',i.last_name,'status',case when i.revoked_at is not null then 'revoked' when i.accepted_at is not null then 'accepted' when i.expires_at<=now() then 'expired' else 'valid' end,'expires_at',i.expires_at) from public.team_invitations i join public.companies c on c.id=i.company_id where i.token_hash=encode(extensions.digest(raw_token,'sha256'),'hex');
$$;
create or replace function public.accept_team_invitation(raw_token text) returns jsonb language plpgsql security definer set search_path=public as $$
declare invitation public.team_invitations;actual_email text;begin if auth.uid() is null then raise exception 'Authentication required';end if;select email into actual_email from auth.users where id=auth.uid();select * into invitation from public.team_invitations where token_hash=encode(extensions.digest(raw_token,'sha256'),'hex') for update;if invitation.id is null then raise exception 'Invitation not found';end if;if invitation.revoked_at is not null then raise exception 'Invitation revoked';end if;if invitation.accepted_at is not null then raise exception 'Invitation already used';end if;if invitation.expires_at<=now() then raise exception 'Invitation expired';end if;if not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null)then raise exception 'Confirm your email before accepting';end if;if lower(actual_email)<>lower(invitation.email) then raise exception 'Sign in with the invited email';end if;if exists(select 1 from public.company_members where company_id=invitation.company_id and user_id=auth.uid())then raise exception 'Membership already exists. Ask an Owner to reactivate or change your role';end if;insert into public.company_members(company_id,user_id,role,status,email,display_name,invited_by,invited_at,accepted_at)values(invitation.company_id,auth.uid(),invitation.role,'active',invitation.email,trim(concat_ws(' ',invitation.first_name,invitation.last_name)),invitation.invited_by,invitation.invited_at,now())on conflict(company_id,user_id)do update set role=excluded.role,status='active',accepted_at=now(),deactivated_at=null;update public.team_invitations set accepted_at=now() where id=invitation.id;update public.users set company_id=invitation.company_id where id=auth.uid();perform public.write_audit(invitation.company_id,'team_invitation_accepted','company_member',auth.uid(),jsonb_build_object('role',invitation.role));return jsonb_build_object('company_id',invitation.company_id,'role',invitation.role);end $$;
create or replace function public.revoke_team_invitation(invitation_id uuid) returns void language plpgsql security definer set search_path=public as $$declare invitation public.team_invitations;begin select*into invitation from public.team_invitations where id=invitation_id and public.has_company_permission(company_id,'team.manage') for update;if invitation.id is null then raise exception 'Invitation not found';end if;update public.team_invitations set revoked_at=now()where id=invitation.id and accepted_at is null;perform public.write_audit(invitation.company_id,'team_invitation_revoked','team_invitation',invitation.id);end $$;
create or replace function public.change_member_role(member_id uuid,new_role public.member_role) returns void language plpgsql security definer set search_path=public as $$declare member public.company_members;caller public.member_role;owners integer;begin perform 1 from public.companies where id=(select company_id from public.company_members where id=member_id) for update;select*into member from public.company_members where id=member_id for update;caller:=public.active_member_role(member.company_id);if caller is null or (caller<>'owner' and not(caller='admin' and member.role not in('owner') and new_role<>'owner'))then raise exception 'Access denied';end if;if member.role='owner' and new_role<>'owner' then select count(*)into owners from public.company_members where company_id=member.company_id and role='owner' and status='active';if owners<=1 then raise exception 'The last active Owner cannot change role';end if;end if;update public.company_members set role=new_role,updated_at=now()where id=member.id;perform public.write_audit(member.company_id,'team_member_role_changed','company_member',member.id,jsonb_build_object('old_role',member.role,'new_role',new_role));end $$;
create or replace function public.set_member_status(member_id uuid,new_status public.membership_status) returns void language plpgsql security definer set search_path=public as $$declare member public.company_members;caller public.member_role;owners integer;begin perform 1 from public.companies where id=(select company_id from public.company_members where id=member_id) for update;select*into member from public.company_members where id=member_id for update;caller:=public.active_member_role(member.company_id);if caller is null or (caller<>'owner' and not(caller='admin' and member.role<>'owner'))then raise exception 'Access denied';end if;if new_status is null or new_status='invited' then raise exception 'Use the invitation flow for invited members';end if;if new_status<>'active' and member.role='owner' and member.status='active' then select count(*)into owners from public.company_members where company_id=member.company_id and role='owner' and status='active';if owners<=1 then raise exception 'The last active Owner cannot be deactivated';end if;end if;update public.company_members set status=new_status,deactivated_at=case when new_status='deactivated'then now()else null end,accepted_at=case when new_status='active'then coalesce(accepted_at,now())else accepted_at end,updated_at=now()where id=member.id;perform public.write_audit(member.company_id,case when new_status='active'then 'team_member_reactivated' else 'team_member_deactivated'end,'company_member',member.id);end $$;
create or replace function public.assign_project_member(target_project uuid,target_user uuid,project_role text default 'crew') returns void language plpgsql security definer set search_path=public as $$declare company uuid;begin select company_id into company from public.projects where id=target_project and public.has_company_permission(company_id,'projects.edit');if company is null then raise exception 'Access denied';end if;if not exists(select 1 from public.company_members where company_id=company and user_id=target_user and status='active')then raise exception 'Member is not active';end if;insert into public.project_members(project_id,user_id,role_on_project,assigned_by)values(target_project,target_user,coalesce(nullif(trim(project_role),''),'crew'),auth.uid())on conflict(project_id,user_id)do update set role_on_project=excluded.role_on_project,assigned_by=auth.uid(),assigned_at=now();perform public.write_audit(company,'project_member_assigned','project',target_project,jsonb_build_object('user_id',target_user,'role',project_role));end $$;
create or replace function public.touch_last_active() returns void language plpgsql security definer set search_path=public as $$begin update public.users set last_active_at=now()where id=auth.uid()and(last_active_at is null or last_active_at<now()-interval '15 minutes');update public.company_members set last_active_at=now()where user_id=auth.uid()and status='active'and(last_active_at is null or last_active_at<now()-interval '15 minutes');end $$;
create or replace function public.update_my_profile(new_name text,new_phone text default null,new_avatar_url text default null) returns void language plpgsql security definer set search_path=public as $$declare membership record;begin if auth.uid()is null then raise exception 'Authentication required';end if;update public.users set full_name=nullif(trim(new_name),''),phone=nullif(trim(new_phone),''),avatar_url=nullif(trim(new_avatar_url),'')where id=auth.uid();update public.company_members set display_name=nullif(trim(new_name),''),updated_at=now()where user_id=auth.uid();for membership in select company_id from public.company_members where user_id=auth.uid()and status='active'loop perform public.write_audit(membership.company_id,'user_profile_updated','user',auth.uid());end loop;end $$;
create or replace function public.get_assigned_projects() returns jsonb language sql stable security definer set search_path=public as $$select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'project_name',p.project_name,'project_number',p.project_number,'status',p.status,'estimated_start_date',p.estimated_start_date,'estimated_completion_date',p.estimated_completion_date,'notes',p.employee_notes,'customer_name',c.name,'job_site',case when j.id is null then null else jsonb_build_object('job_name',j.job_name,'address',j.address,'city',j.city,'state',j.state,'zip',j.zip)end)order by p.estimated_start_date),'[]')from public.project_members pm join public.projects p on p.id=pm.project_id join public.company_members cm on cm.company_id=p.company_id and cm.user_id=auth.uid()and cm.status='active'join public.customers c on c.id=p.customer_id left join public.job_sites j on j.id=p.job_site_id where pm.user_id=auth.uid() and p.company_id=(select company_id from public.users where id=auth.uid());$$;
create or replace function public.get_my_company_context()returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('id',c.id,'name',c.name,'owner_name',c.owner_name,'logo_url',c.logo_url,'address',c.address,'city',c.city,'state',c.state,'zip',c.zip,'phone',c.phone,'email',c.email,'website',c.website,'contractor_license',c.contractor_license,'timezone',c.timezone,'role',cm.role)from public.company_members cm join public.companies c on c.id=cm.company_id where cm.user_id=auth.uid()and cm.status='active'order by(cm.company_id=(select company_id from public.users where id=auth.uid()))desc limit 1;$$;

create or replace function public.send_estimate(target_estimate_id uuid)returns uuid language plpgsql security definer set search_path=public as $$declare result_token uuid;target_company uuid;item_count integer;estimate_total numeric;target_status public.estimate_status;begin select company_id,total,status into target_company,estimate_total,target_status from public.estimates where id=target_estimate_id for update;if target_company is null or not public.has_company_permission(target_company,'estimates.send')then raise exception 'Access denied';end if;select count(*)into item_count from public.estimate_items where estimate_id=target_estimate_id;if item_count=0 or coalesce(estimate_total,0)<=0 then raise exception 'Customer, project, line items, and a valid total are required.';end if;if(select valid_until from public.estimates where id=target_estimate_id)<current_date then raise exception 'Extend the expiration date before sending.';end if;if target_status='approved'then raise exception 'Approved estimates cannot be resent or edited.';end if;update public.estimates set public_token=coalesce(public_token,gen_random_uuid()),public_token_revoked_at=null,status='sent',sent_at=now(),rejected_at=null,rejection_reason=null,rejection_comments=null where id=target_estimate_id returning public_token into result_token;perform public.record_estimate_event(target_estimate_id,'estimate_sent');perform public.write_audit(target_company,'estimate_sent','estimate',target_estimate_id);return result_token;end $$;
create or replace function public.extend_estimate_expiration(target_estimate_id uuid,new_valid_until date)returns void language plpgsql security definer set search_path=public as $$declare target_company uuid;begin select company_id into target_company from public.estimates where id=target_estimate_id;if target_company is null or not public.has_company_permission(target_company,'estimates.edit')then raise exception 'Access denied';end if;if new_valid_until<=current_date then raise exception 'Expiration date must be in the future.';end if;update public.estimates set valid_until=new_valid_until,status='draft'where id=target_estimate_id and status='expired';if not found then raise exception 'Only expired estimates can be extended.';end if;perform public.record_estimate_event(target_estimate_id,'expiration_extended',jsonb_build_object('valid_until',new_valid_until));end $$;
create or replace function public.duplicate_estimate(target_estimate_id uuid)returns uuid language plpgsql security definer set search_path=public as $$declare source public.estimates;new_id uuid;new_number text;begin select*into source from public.estimates where id=target_estimate_id;if source.id is null or not public.has_company_permission(source.company_id,'estimates.create')then raise exception 'Access denied';end if;new_number:=source.estimate_number||'-REV-'||to_char(clock_timestamp(),'YYMMDDHH24MISS');insert into public.estimates(company_id,customer_id,job_site_id,estimate_number,estimate_date,valid_until,status,project_name,scope_of_work,internal_notes,customer_notes,discount_type,discount_value,sales_tax_percent,deposit_percent,estimated_start_date,estimated_completion_date,payment_terms,inclusions,exclusions,subtotal,discount_amount,sales_tax_amount,total,deposit_required,remaining_balance)values(source.company_id,source.customer_id,source.job_site_id,new_number,current_date,greatest(source.valid_until,current_date+30),'draft',source.project_name,source.scope_of_work,source.internal_notes,source.customer_notes,source.discount_type,source.discount_value,source.sales_tax_percent,source.deposit_percent,source.estimated_start_date,source.estimated_completion_date,source.payment_terms,source.inclusions,source.exclusions,source.subtotal,source.discount_amount,source.sales_tax_amount,source.total,source.deposit_required,source.remaining_balance)returning id into new_id;insert into public.estimate_items(estimate_id,company_id,rate_library_id,sort_order,category,phase,service_name,description,customer_description,internal_notes,unit,quantity,waste_percent,material_unit_cost,labor_hours_per_unit,labor_hours,labor_rate,equipment_cost,subcontractor_cost,other_direct_cost,taxable,overhead_percent,profit_markup_percent)select new_id,company_id,rate_library_id,sort_order,category,phase,service_name,description,customer_description,internal_notes,unit,quantity,waste_percent,material_unit_cost,labor_hours_per_unit,labor_hours,labor_rate,equipment_cost,subcontractor_cost,other_direct_cost,taxable,overhead_percent,profit_markup_percent from public.estimate_items where estimate_id=source.id;perform public.write_audit(source.company_id,'estimate_duplicated','estimate',new_id,jsonb_build_object('source_id',source.id));return new_id;end $$;
create or replace function public.update_project_status(target_project_id uuid,new_status public.project_status)returns void language plpgsql security definer set search_path=public as $$declare p public.projects;begin update public.projects set status=new_status,updated_at=now(),actual_start_date=case when new_status='in_progress'then coalesce(actual_start_date,current_date)else actual_start_date end,actual_completion_date=case when new_status='completed'then coalesce(actual_completion_date,current_date)else actual_completion_date end where id=target_project_id and public.has_company_permission(company_id,'projects.edit')returning*into p;if p.id is null then raise exception 'Access denied';end if;insert into public.financial_events(company_id,project_id,event_type,metadata)values(p.company_id,p.id,'project_status_changed',jsonb_build_object('status',new_status));perform public.write_audit(p.company_id,'project_status_changed','project',p.id,jsonb_build_object('status',new_status));end $$;
create or replace function public.add_project_cost(target_project_id uuid,cost_date date,category public.project_cost_category,description text,vendor text,amount numeric,notes text default null)returns uuid language plpgsql security definer set search_path=public as $$declare p public.projects;result_id uuid;begin select*into p from public.projects where id=target_project_id and public.has_company_permission(company_id,'project_costs.create');if p.id is null then raise exception 'Access denied';end if;insert into public.project_costs(company_id,project_id,cost_date,category,description,vendor,amount,notes)values(p.company_id,p.id,cost_date,category,trim(description),nullif(trim(vendor),''),round(greatest(0,amount),2),nullif(trim(notes),''))returning id into result_id;insert into public.financial_events(company_id,project_id,event_type,metadata)values(p.company_id,p.id,'project_cost_added',jsonb_build_object('amount',amount,'category',category));perform public.write_audit(p.company_id,'project_cost_added','project_cost',result_id,jsonb_build_object('project_id',p.id,'amount',amount,'category',category));return result_id;end $$;
create or replace function public.send_change_order(target_change_order_id uuid)returns uuid language plpgsql security definer set search_path=public as $$declare co public.change_orders;result_token uuid;item_count integer;begin select*into co from public.change_orders where id=target_change_order_id for update;if co.id is null or not public.has_company_permission(co.company_id,'change_orders.send')then raise exception 'Access denied';end if;if co.status='approved'then raise exception 'Approved change orders cannot be resent.';end if;select count(*)into item_count from public.change_order_items where change_order_id=co.id;if item_count=0 or co.total<=0 then raise exception 'At least one line item and a valid total are required.';end if;update public.change_orders set public_token=coalesce(public_token,gen_random_uuid()),public_token_revoked_at=null,status='sent',sent_at=now(),rejected_at=null,rejection_reason=null,rejection_comments=null where id=co.id returning public_token into result_token;insert into public.estimate_events(company_id,estimate_id,change_order_id,event_type)values(co.company_id,co.estimate_id,co.id,'change_order_sent');perform public.write_audit(co.company_id,'change_order_sent','change_order',co.id);return result_token;end $$;
create or replace function public.send_invoice(target_invoice_id uuid)returns uuid language plpgsql security definer set search_path=public as $$declare i public.invoices;begin update public.invoices set public_token=coalesce(public_token,gen_random_uuid()),public_token_revoked_at=null,status=case when status='draft'then'sent'else status end,sent_at=coalesce(sent_at,now()),updated_at=now()where id=target_invoice_id and public.has_company_permission(company_id,'invoices.send')and status not in('void','paid')returning*into i;if i.id is null then raise exception 'Access denied';end if;insert into public.financial_events(company_id,project_id,invoice_id,event_type)values(i.company_id,i.project_id,i.id,'invoice_sent');perform public.write_audit(i.company_id,'invoice_sent','invoice',i.id);return i.public_token;end $$;
create or replace function public.create_invoice(payload jsonb,line_items jsonb,allow_overbilling boolean default false)returns uuid language plpgsql security definer set search_path=public as $$declare p public.projects;e public.estimates;company uuid;customer uuid;site uuid;project uuid;estimate uuid;result_id uuid;number text;kind public.invoice_type;row jsonb;sub numeric:=0;taxable_sub numeric:=0;discount numeric;tax_rate numeric;tax numeric;grand numeric;prior numeric:=0;contract numeric:=0;begin project:=nullif(payload->>'project_id','')::uuid;estimate:=nullif(payload->>'estimate_id','')::uuid;kind:=coalesce(nullif(payload->>'invoice_type','')::public.invoice_type,'custom');if project is not null then select*into p from public.projects where id=project and public.has_company_permission(company_id,'invoices.create');if p.id is null then raise exception 'Access denied';end if;company:=p.company_id;customer:=p.customer_id;site:=p.job_site_id;if estimate is not null and estimate<>p.estimate_id then raise exception 'Estimate does not belong to this project';end if;estimate:=p.estimate_id;select p.original_contract_value+coalesce(sum(co.total)filter(where co.status='approved'),0)into contract from public.change_orders co where co.estimate_id=p.estimate_id;select coalesce(sum(total),0)into prior from public.invoices where project_id=p.id and status<>'void';elsif estimate is not null then select*into e from public.estimates where id=estimate and status='approved'and public.has_company_permission(company_id,'invoices.create');if e.id is null then raise exception 'Access denied';end if;company:=e.company_id;customer:=e.customer_id;site:=e.job_site_id;contract:=e.total;select coalesce(sum(total),0)into prior from public.invoices where estimate_id=e.id and status<>'void';else raise exception 'An approved estimate or project is required';end if;if jsonb_typeof(line_items)<>'array'or jsonb_array_length(line_items)=0 then raise exception 'At least one line item is required';end if;for row in select*from jsonb_array_elements(line_items)loop if char_length(trim(coalesce(row->>'description','')))=0 then raise exception 'Every item needs a description';end if;sub:=sub+round(greatest(0,coalesce((row->>'quantity')::numeric,0))*greatest(0,coalesce((row->>'unit_price')::numeric,0)),2);if coalesce((row->>'taxable')::boolean,false)then taxable_sub:=taxable_sub+round(greatest(0,coalesce((row->>'quantity')::numeric,0))*greatest(0,coalesce((row->>'unit_price')::numeric,0)),2);end if;end loop;discount:=least(sub,greatest(0,coalesce((payload->>'discount_amount')::numeric,0)));tax_rate:=greatest(0,coalesce((payload->>'sales_tax_percent')::numeric,0));tax:=round(greatest(0,taxable_sub-(case when sub>0 then discount*(taxable_sub/sub)else 0 end))*tax_rate/100,2);grand:=round(sub-discount+tax,2);if contract>0 and prior+grand>contract and not allow_overbilling then raise exception 'This invoice exceeds the remaining contract value. Confirm overbilling to continue.';end if;number:=coalesce(nullif(trim(payload->>'invoice_number'),''),'INV-'||to_char(current_date,'YYYY')||'-'||lpad(((select count(*)+1 from public.invoices where company_id=company and extract(year from created_at)=extract(year from now())))::text,4,'0'));insert into public.invoices(company_id,customer_id,job_site_id,project_id,estimate_id,invoice_number,invoice_type,invoice_date,due_date,po_number,customer_notes,internal_notes,payment_terms,subtotal,discount_amount,sales_tax_percent,sales_tax_amount,total,balance_due)values(company,customer,site,project,estimate,number,kind,coalesce((payload->>'invoice_date')::date,current_date),coalesce((payload->>'due_date')::date,current_date+30),nullif(trim(payload->>'po_number'),''),nullif(trim(payload->>'customer_notes'),''),nullif(trim(payload->>'internal_notes'),''),nullif(trim(payload->>'payment_terms'),''),sub,discount,tax_rate,tax,grand,grand)returning id into result_id;insert into public.invoice_items(invoice_id,company_id,sort_order,description,quantity,unit,unit_price,taxable,amount)select result_id,company,ordinality-1,trim(value->>'description'),greatest(0,coalesce((value->>'quantity')::numeric,0)),coalesce(nullif(value->>'unit',''),'each'),greatest(0,coalesce((value->>'unit_price')::numeric,0)),coalesce((value->>'taxable')::boolean,false),round(greatest(0,coalesce((value->>'quantity')::numeric,0))*greatest(0,coalesce((value->>'unit_price')::numeric,0)),2)from jsonb_array_elements(line_items)with ordinality;insert into public.financial_events(company_id,project_id,invoice_id,event_type,metadata)values(company,project,result_id,'invoice_created',jsonb_build_object('type',kind));perform public.write_audit(company,'invoice_created','invoice',result_id,jsonb_build_object('type',kind));return result_id;end $$;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('profile-avatars','profile-avatars',true,2097152,array['image/png','image/jpeg','image/webp'])on conflict(id)do nothing;
create policy "avatar public read" on storage.objects for select using(bucket_id='profile-avatars');
create policy "user upload avatar" on storage.objects for insert to authenticated with check(bucket_id='profile-avatars'and(storage.foldername(name))[1]=auth.uid()::text);
create policy "user update avatar" on storage.objects for update to authenticated using(bucket_id='profile-avatars'and(storage.foldername(name))[1]=auth.uid()::text);
create policy "user delete avatar" on storage.objects for delete to authenticated using(bucket_id='profile-avatars'and(storage.foldername(name))[1]=auth.uid()::text);

revoke execute on function public.create_team_invitation(uuid,text,public.member_role,text,text),public.accept_team_invitation(text),public.revoke_team_invitation(uuid),public.change_member_role(uuid,public.member_role),public.set_member_status(uuid,public.membership_status),public.assign_project_member(uuid,uuid,text),public.touch_last_active(),public.update_my_profile(text,text,text),public.get_assigned_projects(),public.get_my_company_context() from public,anon;
revoke execute on function public.get_public_invitation(text) from public,anon,authenticated;
grant execute on function public.create_team_invitation(uuid,text,public.member_role,text,text),public.accept_team_invitation(text),public.revoke_team_invitation(uuid),public.change_member_role(uuid,public.member_role),public.set_member_status(uuid,public.membership_status),public.assign_project_member(uuid,uuid,text),public.touch_last_active(),public.update_my_profile(text,text,text),public.get_assigned_projects(),public.get_my_company_context() to authenticated;
grant execute on function public.get_public_invitation(text) to anon,authenticated;

